from pathlib import Path

SRC=Path('assets/driver-config-v81.js')
DST=Path('assets/driver-config-v230.js')
s=SRC.read_text()
old="function loftFit(p){const launch=classify('launch'),spin=classify('spin'),aoa=numeric('aoa');let loft=10.5,reasons=[],conflict=false;if(launch==='low'){loft+=1;reasons.push('lower launch');}else if(launch==='high'){loft-=1;reasons.push('higher launch');}if(spin==='low'){loft+=.5;reasons.push('lower spin');}else if(spin==='high'){loft-=.5;reasons.push('higher spin');}conflict=(launch==='low'&&spin==='high')||(launch==='high'&&spin==='low');if(aoa!=null&&aoa<=-2){loft+=.5;reasons.push('downward attack angle');}else if(aoa!=null&&aoa>=4){loft-=.5;reasons.push('upward attack angle');}if(p?.player==='lowspin')loft+=.5;loft=Math.round(clamp(loft,8,12)*2)/2;const lo=clamp(loft-.5,8,12),hi=clamp(loft+.5,8,12);let reason=reasons.length?`Driven by ${reasons.slice(0,3).join(', ')}.`:'Neutral starting loft from the information provided.';if(conflict)reason+=' Launch and spin point in competing loft directions, so launch-monitor validation matters more than the nominal loft.';return {loft,range:`${lo.toFixed(1)}°–${hi.toFixed(1)}°`,reason,conflict};}"
new="const CONFIG_RANGE_MAPS={speed:{under75:72,'75-84':80,'85-89':87,'90-94':92,'95-99':97,'100-104':102,'105-109':107,'110-114':112,'115plus':118},launch:{under8:7,'8-10':9,'10-12':11,'12-14':13,'14-16':15,'16-18':17,'18-20':19,'20plus':21},spin:{under1500:1400,'1500-1749':1625,'1750-1999':1875,'2000-2249':2125,'2250-2499':2375,'2500-2749':2625,'2750-2999':2875,'3000-3499':3250,'3500plus':3650}};\nfunction configValue(id){const m=metric(id);if(!m||!answered(m.value)||m.mode==='unknown')return null;if(m.mode==='exact')return Number(m.value);if(m.mode==='range')return CONFIG_RANGE_MAPS[id]?.[m.value]??null;return null;}\nfunction configSmooth(x){x=clamp(x,0,1);return x*x*(3-2*x);}\nfunction configFlightTargets(speed){speed=Number(speed);if(!Number.isFinite(speed))return null;return {launch:clamp(14.5-.08*(speed-70),10.8,14.7),spin:clamp(2850-16*(speed-70),2100,2900)};}\nfunction configFlightNeeds(speed,launch,spin){const t=configFlightTargets(speed);if(!t)return null;return {target:t,launchLow:configSmooth((t.launch-launch-.25)/3),launchHigh:configSmooth((launch-t.launch-3.25)/3.5),spinLow:configSmooth((t.spin-spin-100)/800),spinHigh:configSmooth((spin-t.spin-350)/900)};}\nfunction loftFit(p){const speed=configValue('speed'),launchValue=configValue('launch'),spinValue=configValue('spin');if(speed==null||launchValue==null||spinValue==null){const launch=classify('launch'),spin=classify('spin'),aoa=numeric('aoa');let loft=10.5,reasons=[],conflict=false;if(launch==='low'){loft+=1;reasons.push('lower launch');}else if(launch==='high'){loft-=1;reasons.push('higher launch');}if(spin==='low'){loft+=.5;reasons.push('lower spin');}else if(spin==='high'){loft-=.5;reasons.push('higher spin');}conflict=(launch==='low'&&spin==='high')||(launch==='high'&&spin==='low');if(aoa!=null&&aoa<=-2){loft+=.5;reasons.push('downward attack angle');}else if(aoa!=null&&aoa>=4){loft-=.5;reasons.push('upward attack angle');}if(p?.player==='lowspin')loft+=.5;loft=Math.round(clamp(loft,8,12)*2)/2;const lo=clamp(loft-.5,8,12),hi=clamp(loft+.5,8,12);let reason=reasons.length?`Driven by ${reasons.slice(0,3).join(', ')}.`:'Neutral starting loft from the information provided.';if(conflict)reason+=' Launch and spin point in competing loft directions, so launch-monitor validation matters more than the nominal loft.';return {loft,range:`${lo.toFixed(1)}°–${hi.toFixed(1)}°`,reason,conflict};}\nconst n=configFlightNeeds(speed,launchValue,spinValue),aoa=numeric('aoa');let loft=10.5,reasons=[],conflict=false;const launchAdj=n.launchLow-n.launchHigh,spinAdj=.5*(n.spinLow-n.spinHigh);loft+=launchAdj+spinAdj;if(n.launchLow>=.08)reasons.push('launch below your speed-based window');else if(n.launchHigh>=.08)reasons.push('launch above your speed-based window');if(n.spinLow>=.08)reasons.push('spin below your speed-based window');else if(n.spinHigh>=.08)reasons.push('spin above your speed-based window');conflict=(n.launchLow>=.08&&n.spinHigh>=.08)||(n.launchHigh>=.08&&n.spinLow>=.08);if(aoa!=null&&aoa<=-2){loft+=.5;reasons.push('downward attack angle');}else if(aoa!=null&&aoa>=4){loft-=.5;reasons.push('upward attack angle');}if(p?.player==='lowspin')loft+=.5;loft=Math.round(clamp(loft,8,12)*2)/2;const lo=clamp(loft-.5,8,12),hi=clamp(loft+.5,8,12);let reason=reasons.length?`Driven by ${reasons.slice(0,3).join(', ')}.`:'Neutral starting loft from the information provided.';if(conflict)reason+=' Launch and spin point in competing loft directions, so launch-monitor validation matters more than the nominal loft.';return {loft,range:`${lo.toFixed(1)}°–${hi.toFixed(1)}°`,reason,conflict};}"
assert old in s, 'expected v81 loftFit not found'
s=s.replace(old,new,1)
s=s.replace('// FORM 14.10.3 — recommendation evidence strength + loft/configuration + shaft starting fit','// FORM 14.10.4 — speed-aware continuous loft configuration + recommendation evidence + shaft starting fit',1)
old_export="window.FORM_DRIVER_CONFIG_V81={recommendationEvidence,loftFit,shaftFit,profileInsight,separation,currentReliability,currentContext,decorate};"
new_export="const CONFIG_API={recommendationEvidence,loftFit,shaftFit,profileInsight,separation,currentReliability,currentContext,decorate};window.FORM_DRIVER_CONFIG_V81=CONFIG_API;window.FORM_DRIVER_CONFIG_V230=CONFIG_API;"
assert old_export in s, 'expected v81 export not found'
s=s.replace(old_export,new_export,1)
DST.write_text(s)
print(f'wrote {DST} ({len(s)} bytes)')
